    await check('contact_archive_restore_readonly',async()=>{const card=()=>page.getByRole('article').filter({hasText:'W2 Synthetic Contact'});await card().getByRole('button',{name:'Editar contacto',exact:true}).click();await page.getByRole('button',{name:'Archivar contacto',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Confirmar',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.reload();await card().getByRole('button',{name:'Editar contacto',exact:true}).click();await expect(page.getByLabel('Nombre del contacto',{exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Guardar contacto',exact:true})).toBeDisabled();await page.getByRole('button',{name:'Restaurar contacto',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Confirmar',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.reload();await card().getByRole('button',{name:'Editar contacto',exact:true}).click();await expect(page.getByLabel('Nombre del contacto',{exact:true})).toBeEnabled();await page.getByRole('button',{name:'Cerrar panel',exact:true}).click()})
    await check('customer_archive_restore_persist',async()=>{await page.getByRole('button',{name:'Archivar cliente',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Confirmar',exact:true}).click();await expect(page.getByRole('button',{name:'Restaurar cliente',exact:true})).toBeVisible();await page.reload();await page.getByRole('button',{name:'Restaurar cliente',exact:true}).click();await page.getByRole('dialog').getByRole('button',{name:'Confirmar',exact:true}).click();await expect(page.getByRole('button',{name:'Archivar cliente',exact:true})).toBeVisible();await page.reload();await expect(page.getByRole('heading',{name:'W2 UI Synthetic Company',exact:true})).toBeVisible()})
