    await check('task_reopen_start_update_cancel',async()=>{await page.getByRole('button',{name:/W2 UI Synthetic Task/}).first().click();await page.getByRole('button',{name:'Reabrir tarea',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.getByRole('button',{name:/W2 UI Synthetic Task/}).first().click();await page.getByRole('button',{name:'Iniciar tarea',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.getByRole('button',{name:/W2 UI Synthetic Task/}).first().click();await page.getByLabel('Título',{exact:true}).fill('W2 UI Synthetic Task Edited');await page.getByRole('button',{name:'Guardar agenda',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.getByRole('button',{name:/W2 UI Synthetic Task Edited/}).first().click();await page.getByRole('button',{name:'Cancelar actividad',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);if(sql(`select status from public.tasks where workspace_id='${wa}' and title='W2 UI Synthetic Task Edited'`)!=='cancelled')throw Error('TASK_STATE_NOT_PERSISTED');await page.getByRole('button',{name:/W2 UI Synthetic Task Edited/}).first().click();await expect(page.getByLabel('Título',{exact:true})).toBeDisabled();await page.getByRole('button',{name:'Reabrir tarea',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.getByRole('button',{name:/W2 UI Synthetic Task Edited/}).first().click();await expect(page.getByLabel('Prioridad',{exact:true})).toHaveValue('high');await expect(page.getByLabel('Responsable autorizado',{exact:true})).toHaveValue(users.memberA.id);await page.getByRole('button',{name:'Completar',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);if(sql(`select status from public.tasks where workspace_id='${wa}' and title='W2 UI Synthetic Task Edited'`)!=='completed')throw Error('CANCELLED_TASK_REOPEN_NOT_PERSISTED')})
    await check('meeting_update_complete_no_show',async()=>{async function create(title){await page.getByRole('button',{name:'Nueva cita',exact:true}).click();await page.getByLabel('Título',{exact:true}).fill(title);await page.getByLabel('Inicio',{exact:true}).fill(day+'T17:00');await page.getByLabel('Fin',{exact:true}).fill(day+'T18:00');await page.getByRole('button',{name:'Guardar agenda',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0)}if(report)report.w2_meeting_state_step='CREATE_FIRST';await create('W2 UI State Meeting');if(report)report.w2_meeting_state_step='EDIT_FIRST';await page.getByRole('button',{name:/W2 UI State Meeting/}).first().click();await page.getByLabel('Título',{exact:true}).fill('W2 UI State Meeting Edited');await page.getByRole('button',{name:'Reprogramar reunión',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);await page.getByRole('button',{name:/W2 UI State Meeting Edited/}).first().click();await page.getByRole('button',{name:'Completar',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);if(report)report.w2_meeting_state_step='CREATE_SECOND';await create('W2 UI No Show Meeting');if(report)report.w2_meeting_state_step='NO_SHOW_SECOND';await page.getByRole('button',{name:/W2 UI No Show Meeting/}).first().click();await page.getByRole('button',{name:'Marcar ausencia',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);if(sql(`select status from public.calendar_events where workspace_id='${wa}' and title='W2 UI State Meeting Edited'`)!=='completed'||sql(`select status from public.calendar_events where workspace_id='${wa}' and title='W2 UI No Show Meeting'`)!=='no_show')throw Error('MEETING_STATE_NOT_PERSISTED')})
